def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A full-width horizontal separator divides matching-color markers above
    # and below. Draw the incremented marker color in the columns shared by
    # their horizontal extents, from the top marker down to the separator.
    sep = next((r for r, row in enumerate(grid[1:], start=1) if len(set(row)) == 1 and row[0] != 0), None)
    if sep is None:
        return out
    top_color = next((v for v in grid[0] if v != 0), None)
    if top_color is None:
        return out
    top_cols = {c for c, v in enumerate(grid[0]) if v == top_color}
    bottom_row = next((row for row in reversed(grid[sep + 1:]) if any(v != 0 for v in row)), None)
    if bottom_row is None:
        return out
    bottom_cols = {c for c, v in enumerate(bottom_row) if v == top_color}
    color = (top_color + 1) % 10
    for c in top_cols & bottom_cols:
        for r in range(1, sep):
            out[r][c] = color
    return out

